import { useSyncExternalStore } from 'react';

// A minimal external store shared across micro-frontends via `window`,
// wired up with useSyncExternalStore so each remote's React tree stays
// in sync with the same source of truth without prop drilling across
// federation boundaries.
function getStore() {
  if (!window.__MFE_STORE__) {
    let state = { currentUser: null, selectedDepartment: null };
    const listeners = new Set();

    window.__MFE_STORE__ = {
      getState: () => state,
      setState: (partial) => {
        state = { ...state, ...partial };
        listeners.forEach((listener) => listener());
      },
      subscribe: (listener) => {
        listeners.add(listener);
        return () => listeners.delete(listener);
      },
    };
  }
  return window.__MFE_STORE__;
}

export function setSharedState(partial) {
  getStore().setState(partial);
}

export function useSharedStore(selector = (state) => state) {
  const store = getStore();
  return useSyncExternalStore(
    store.subscribe,
    () => selector(store.getState())
  );
}
